function applyEvents(initial, events) {
  if (!Number.isInteger(initial)) throw new Error('Invalid initial');
  let balanceMinor = initial;
  const applied = [];
  const queued = [];
  const appliedSet = new Set();
  const queuedSet = new Set();
  for (const event of events) {
    const amount = event.amountMinor;
    if (!Number.isInteger(amount)) throw new Error('Invalid amountMinor');
    const id = event.id;
    if (event.synced) {
      if (appliedSet.has(id)) continue;
      appliedSet.add(id);
      applied.push(id);
      balanceMinor += amount;
      if (queuedSet.has(id)) queuedSet.delete(id);
    } else {
      if (!appliedSet.has(id) && !queuedSet.has(id)) {
        queuedSet.add(id);
        queued.push(id);
      }
    }
  }
  return { balanceMinor: balanceMinor, applied: applied, queued: queued.filter(id => !appliedSet.has(id)) };
}

function applyEvents(initial, events) {
  if (!Number.isInteger(initial)) {
    throw new Error("initial must be an integer");
  }

  const appliedIds = new Set();
  const queuedIds = new Set();
  const applied = [];
  const queued = [];
  let balanceMinor = initial;

  for (const event of events) {
    const { id, amountMinor, synced } = event;

    if (!Number.isInteger(amountMinor) || !Number.isFinite(amountMinor)) {
      throw new Error("amountMinor must be a finite integer");
    }

    if (appliedIds.has(id)) {
      continue;
    }

    if (synced) {
      if (queuedIds.has(id)) {
        queuedIds.delete(id);
        const index = queued.indexOf(id);
        if (index !== -1) {
          queued.splice(index, 1);
        }
      }

      appliedIds.add(id);
      applied.push(id);
      balanceMinor += amountMinor;
    } else if (!queuedIds.has(id)) {
      queuedIds.add(id);
      queued.push(id);
    }
  }

  return { balanceMinor, applied, queued };
}

function applyEvents(initial, events) {
  if (!Number.isInteger(initial)) {
    throw new Error('initial must be an integer');
  }
  if (!Array.isArray(events)) {
    throw new Error('events must be an array');
  }
  var balance = initial;
  var applied = [];
  var queued = [];
  var state = new Map();
  for (var i = 0; i < events.length; i++) {
    var e = events[i];
    if (e === null || typeof e !== 'object') {
      throw new Error('event must be an object');
    }
    var amount = e.amountMinor;
    if (!Number.isInteger(amount)) {
      throw new Error('amountMinor must be a finite integer');
    }
    var id = e.id;
    var st = state.get(id);
    if (e.synced) {
      if (st === 'applied') {
        continue;
      }
      if (st === 'queued') {
        queued.splice(queued.indexOf(id), 1);
      }
      state.set(id, 'applied');
      applied.push(id);
      balance += amount;
    } else if (st === undefined) {
      state.set(id, 'queued');
      queued.push(id);
    }
  }
  return { balanceMinor: balance, applied: applied, queued: queued };
}
